/**
 * Geometry observed from re-mounting one flash page bin via the
 * dynamic, read-only FS (same pattern as `simple_flash_fs_tar -i`).
 */
struct InspectFileResult
{
	bool                   found            = false;
	std::size_t            file_len         = 0;
	std::size_t            data_pages_count = 0;
	std::size_t            inode_data_size  = 0;
	std::size_t            free_data_pages  = 0;
	std::vector<std::byte> contents;
};

/**
 * Mount `bin_path` via dynamic::SimpleFlashFsReadOnly and look up
 * `file_name`. Picks the highest inode_version_number for that name
 * to skip stale COW versions that have not yet been erased.
 */
InspectFileResult inspect_file_dynamic( const std::string &       bin_path,
                                        const std::string_view &  file_name )
{
	InspectFileResult result;

	if( !std::filesystem::exists( bin_path ) ) {
		return result;
	}

	::SimpleFlashFs::SimPc::SimFlashFsFlashMemory inspect_mem( bin_path );
	::SimpleFlashFs::dynamic::SimpleFlashFsReadOnly inspect_fs( &inspect_mem );

	if( !inspect_fs.init() ) {
		return result;
	}

	result.free_data_pages = inspect_fs.get_number_of_free_data_pages();

	decltype( inspect_fs.get_all_inodes( false ) )::value_type latest{};

	for( auto inode : inspect_fs.get_all_inodes( false ) ) {
		if( inode->inode.file_name.empty() ) {
			continue;
		}
		if( inode->inode.file_name != file_name ) {
			continue;
		}
		if( !latest ||
		    inode->inode.inode_version_number >
		        latest->inode.inode_version_number ) {
			latest = inode;
		}
	}

	if( latest ) {
		result.found            = true;
		result.file_len         = latest->inode.file_len;
		result.data_pages_count = latest->inode.data_pages.size();
		result.inode_data_size  = latest->inode.inode_data.size();

		if( latest->inode.file_len > 0 ) {
			result.contents.resize( latest->inode.file_len );
			latest->seek( 0 );
			std::size_t bytes_read =
				latest->read( result.contents.data(), result.contents.size() );
			result.contents.resize( bytes_read );
		}
	}

	return result;
}

/**
 * In the 2-page FS only ONE of the two bin files is currently active
 * (the other is sealed/blank). Try both and return whichever holds
 * our file. Falls back to whichever could even be inspected.
 */
InspectFileResult inspect_active_page( const std::string &      file1,
                                       const std::string &      file2,
                                       const std::string_view & file_name )
{
	auto r1 = inspect_file_dynamic( file1, file_name );
	if( r1.found ) {
		return r1;
	}
	auto r2 = inspect_file_dynamic( file2, file_name );
	if( r2.found ) {
		return r2;
	}
	// neither held the file; return r1 so caller still gets fs stats
	return r1;
}

/**
 * Test-case scaffolding analogous to TestCaseH7Base in test_H7TwoFace.cc
 * but parameterized by a functor that has access to the underlying
 * bin file paths so the inspector can mount them after deinit.
 */
class TestCaseH7Truncate : public TestCaseBase<bool>
{
public:
	using Func = std::function<bool( const std::string & file1,
	                                 const std::string & file2 )>;

protected:
	std::optional<::SimpleFlashFs::SimPc::SimSTM32InternalFlashPc> mem1;
	std::optional<::SimpleFlashFs::SimPc::SimSTM32InternalFlashPc> mem2;
	std::string                                                     file_name;
	std::string                                                     file1;
	std::string                                                     file2;
	Func                                                            func;

public:
	TestCaseH7Truncate( const std::string & name_, Func func_ )
	: TestCaseBase<bool>( name_, true ),
	  file_name( "." + name ),
	  file1( file_name + "_page1.bin" ),
	  file2( file_name + "_page2.bin" ),
	  func( func_ )
	{
	}

	void clear( const std::string & f )
	{
		if( std::filesystem::exists( f ) ) {
			if( !std::filesystem::remove( f ) ) {
				throw STDERR_EXCEPTION(
					Tools::format( "cannot delete %s", f ) );
			}
		}
	}

	bool run() override
	{
		clear( file1 );
		clear( file2 );

		// the 4-arg ctor must be used: it creates/resizes the file
		// (the 3-arg overload would try to open an existing file)
		mem1.emplace( file1, SFF_PAGE_SIZE, SFF_MAX_SIZE, false );
		mem2.emplace( file2, SFF_PAGE_SIZE, SFF_MAX_SIZE, false );
		H7TwoFace::set_memory_interface( &mem1.value(), &mem2.value() );

		bool ret = false;
		try {
			ret = func( file1, file2 );
		} catch( ... ) {
			H7TwoFace::set_memory_interface( nullptr, nullptr );
			mem1.reset();
			mem2.reset();
			throw;
		}

		// detach H7TwoFace so the singleton FS drops its references,
		// then release the flash simulators so their fstream handles
		// are flushed/closed before the inspector reopens the files
		H7TwoFace::set_memory_interface( nullptr, nullptr );
		mem1.reset();
		mem2.reset();
		return ret;
	}
};

// page_size on this side is 512 bytes (SFF_PAGE_SIZE), so the inline
// threshold is around ~400 bytes. Numbers chosen to exercise inline
// vs. external paths cleanly.
constexpr const char *  k_test_file_name = "trunc.test";
constexpr std::size_t   k_inline_size    = 100;
constexpr std::size_t   k_inline_grown   = 300;
constexpr std::size_t   k_large_size     = 4 * SFF_PAGE_SIZE + 123; // 5 pages
constexpr std::size_t   k_shrink_target  = 1 * SFF_PAGE_SIZE + 50;  // 2 pages

bool check_zero_padding( const std::vector<std::byte> & contents,
                         std::size_t                     from,
                         std::size_t                     to,
                         const char *                    label )
{
	for( std::size_t i = from; i < to; i++ ) {
		if( contents[i] != std::byte( 0 ) ) {
			CPPDEBUG( Tools::format(
				"%s: expected zero at offset %d, got 0x%02X", label, i,
				static_cast<unsigned>( contents[i] ) ) );
			return false;
		}
	}
	return true;
}

bool check_filler( const std::vector<std::byte> & contents,
                   std::size_t                     from,
                   std::size_t                     to,
                   std::byte                       expected,
                   const char *                    label )
{
	for( std::size_t i = from; i < to; i++ ) {
		if( contents[i] != expected ) {
			CPPDEBUG( Tools::format(
				"%s: expected 0x%02X at offset %d, got 0x%02X", label,
				static_cast<unsigned>( expected ), i,
				static_cast<unsigned>( contents[i] ) ) );
			return false;
		}
	}
	return true;
}

