std::shared_ptr<TestCaseBase<bool>> test_case_static_TwoFace_truncate_enlarge()
{
	return std::make_shared<TestCaseH7Truncate>(
		__FUNCTION__,
		[]( const std::string & file1, const std::string & file2 ) {
			{
				auto f = H7TwoFace::open(
					k_test_file_name,
					std::ios_base::out | std::ios_base::trunc );
				if( !f ) {
					return false;
				}

				std::vector<std::byte> data( k_inline_size, std::byte( 'A' ) );
				if( f->write( data.data(), data.size() ) != data.size() ) {
					return false;
				}

				if( !f->truncate( k_inline_grown ) ) {
					CPPDEBUG( "truncate failed" );
					return false;
				}

				if( f->file_size() != k_inline_grown ) {
					return false;
				}
			}

			auto inspect = inspect_active_page( file1, file2, k_test_file_name );
			if( !inspect.found ) {
				CPPDEBUG( "inspect: file not found in either page" );
				return false;
			}
			if( inspect.file_len != k_inline_grown ) {
				CPPDEBUG( Tools::format(
					"inspect: file_len=%d expected %d", inspect.file_len,
					k_inline_grown ) );
				return false;
			}
			if( inspect.data_pages_count != 0 ) {
				CPPDEBUG( Tools::format(
					"inspect: data_pages_count=%d expected 0 (inline)",
					inspect.data_pages_count ) );
				return false;
			}
			if( !check_filler( inspect.contents, 0, k_inline_size,
			                   std::byte( 'A' ), "twoface enlarge orig" ) ) {
				return false;
			}
			if( !check_zero_padding( inspect.contents, k_inline_size,
			                         k_inline_grown,
			                         "twoface enlarge padding" ) ) {
				return false;
			}
			return true;
		} );
}

